#!/usr/bin/env bash
# Builds the EV Stats macOS app + widget and installs it into ~/Applications.
# Reads WIDGET_TOKEN (and optional WIDGET_BASE_URL) from ../.env.local.
set -euo pipefail
cd "$(dirname "$0")"

ENV_FILE=../.env.local
get() { [ -f "$ENV_FILE" ] && grep -E "^$1=" "$ENV_FILE" | tail -1 | cut -d= -f2- || true; }
BASE_URL=$(get WIDGET_BASE_URL); BASE_URL=${BASE_URL:-http://localhost:3000}
TOKEN=$(get WIDGET_TOKEN)

cat > Shared/AppConfig.swift <<SWIFT
// Generated by build.sh — do not commit.
enum AppConfig {
    static let baseURL = "$BASE_URL"
    static let token = "$TOKEN"
}
SWIFT

command -v xcodegen >/dev/null || { echo "Install xcodegen: brew install xcodegen"; exit 1; }
xcodegen generate --quiet
xcodebuild -project EVStats.xcodeproj -scheme EVStats -configuration Release \
  -derivedDataPath build CODE_SIGN_IDENTITY=- CODE_SIGNING_ALLOWED=YES -quiet build

APP=build/Build/Products/Release/EVStats.app
mkdir -p ~/Applications
rm -rf ~/Applications/EVStats.app
cp -R "$APP" ~/Applications/
open ~/Applications/EVStats.app
echo "Installed ~/Applications/EVStats.app"
